import{_ as s,o as e,c as t,a5 as n}from"./chunks/framework.CXroN2RO.js";const i="/study/images/compilers/tokens-ast-and-type-checking.svg",k=JSON.parse('{"title":"トークン・AST・型検査 — C++のソースを読み解く","description":"","frontmatter":{"title":"トークン・AST・型検査 — C++のソースを読み解く","study":{"source":"新規執筆","section":"reference","format":"article","status":"published","domain":"compilers","summary":"字句解析で得たトークンを構文木に組み立て、名前の参照先、式の型、暗黙の型変換を確かめる。","aliases":["コンパイラフロントエンド","字句解析","lexer","トークン","token","構文解析","parser","抽象構文木","AST","型検査","意味解析","Sema","Clang"],"verification":"Clang 14.0.6でASTと二つの診断を確認し、Clang公式資料に照合（2026-11-06）"}},"headers":[],"relativePath":"compilers/tokens-ast-and-type-checking.md","filePath":"compilers/tokens-ast-and-type-checking.md"}'),l={name:"compilers/tokens-ast-and-type-checking.md"};function r(p,a,o,d,h,c){return e(),t("div",null,[...a[0]||(a[0]=[n(`<h1 id="トークン・ast・型検査-—-c-のソースを読み解く" tabindex="-1">トークン・AST・型検査 — C++のソースを読み解く <a class="header-anchor" href="#トークン・ast・型検査-—-c-のソースを読み解く" aria-label="Permalink to &quot;トークン・AST・型検査 — C++のソースを読み解く&quot;">​</a></h1><p><code>value + step * 2u</code> からコードを生成するには、<code>value</code> と <code>step</code> の参照先の宣言、演算を組み立てる順序、各演算で使う型を決める必要があります。<strong>フロントエンド</strong>は前処理の結果を受け取り、言語の規則に従ってこれらを決め、後続の処理に渡す表現を作ります。<a href="/study/runtime/cpp-internals/build-pipeline-journey.html">コンパイル全体の流れ</a> · <a href="https://clang.llvm.org/docs/InternalsManual.html#the-parser-library" target="_blank" rel="noreferrer">Clangフロントエンドの内部構成</a></p><div class="language-cpp vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">cpp</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">double</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> adjust</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">double</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;"> value</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">unsigned</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;"> step</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) {</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    return</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> value </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">+</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> step </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">*</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 2</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">u</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><figure class="study-figure"><img src="`+i+`" alt="return文を7個のトークンに分ける。加算の右側に乗算の部分木ができ、型検査で乗算結果をunsigned intからdoubleへ変換する。" width="760" height="322" loading="lazy"><figcaption>式の読み取りを3つの観点から見た図です。木の乗算ノードは、加算に渡す値を作ります。<a href="/study/images/compilers/tokens-ast-and-type-checking.svg" target="_blank" rel="noopener noreferrer">フロントエンドの図を拡大</a></figcaption></figure><h2 id="文字からトークンを取り出す" tabindex="-1">文字からトークンを取り出す <a class="header-anchor" href="#文字からトークンを取り出す" aria-label="Permalink to &quot;文字からトークンを取り出す&quot;">​</a></h2><p><strong>字句解析（lexing）<strong>は、入力の文字列から、名前、数値リテラル、演算子などの単位を認識する処理です。一つずつ取り出した単位を</strong>トークン</strong>と呼びます。この <code>return</code> 文では、キーワード <code>return</code>、識別子 <code>value</code>、記号 <code>+</code>、識別子 <code>step</code>、記号 <code>*</code>、数値リテラル <code>2u</code>、記号 <code>;</code> が並びます。<code>2u</code> は接尾辞を含めて一つのトークンです。Clangのパーサーは、マクロなどを処理する前処理器からトークンを受け取ります。<a href="https://clang.llvm.org/docs/InternalsManual.html#the-lexer-and-preprocessor-library" target="_blank" rel="noreferrer">ClangのLexerとPreprocessor</a></p><h2 id="トークンを文や式の木に組み立てる" tabindex="-1">トークンを文や式の木に組み立てる <a class="header-anchor" href="#トークンを文や式の木に組み立てる" aria-label="Permalink to &quot;トークンを文や式の木に組み立てる&quot;">​</a></h2><p>**構文解析（parsing）**では、トークンの列を文法に沿って組み立てます。この式では <code>*</code> の優先順位が <code>+</code> より高いため、<code>step * 2u</code> が一つの部分式になり、加算の右側に入ります。こうした入れ子を、式、文、宣言などを表すノードで記録したものが <strong>AST（抽象構文木）</strong> です。ClangのASTには、ソースを書き換えるツールでも扱えるように、明示的な丸括弧を表すノードが残る場合があります。<a href="https://clang.llvm.org/docs/IntroductionToTheClangAST.html" target="_blank" rel="noreferrer">Clang ASTの構造</a></p><h2 id="名前を解決し、型を確かめる" tabindex="-1">名前を解決し、型を確かめる <a class="header-anchor" href="#名前を解決し、型を確かめる" aria-label="Permalink to &quot;名前を解決し、型を確かめる&quot;">​</a></h2><p><strong>意味解析</strong>では、言語の規則に従って名前の参照先や式の型を決めます。<code>step</code> は関数の第2引数を指し、<code>step</code> と <code>2u</code> の乗算は <code>unsigned int</code> で行います。その積を <code>double</code> に変換して、<code>value</code> と加算します。Clangでは、パーサーが構文を読み進めながら意味解析の <code>Sema</code> を呼び出します。ASTには、元の式に対応するノードに加え、暗黙の変換を表す <code>ImplicitCastExpr</code> も現れます。<a href="https://clang.llvm.org/docs/InternalsManual.html#the-sema-library" target="_blank" rel="noreferrer">ClangのSemaとAST</a></p><table tabindex="0"><thead><tr><th>ソースに加えた変更</th><th>診断を調べるときの観点</th></tr></thead><tbody><tr><td><code>return</code> 文の末尾から <code>;</code> を取り除く</td><td>文を終えるトークンを構文解析器が見つけられない</td></tr><tr><td><code>step * 2u</code> を <code>&quot;up&quot; * 2u</code> にする</td><td>乗算の形は読めるが、文字列リテラルと整数に対する乗算は型の規則を満たさない</td></tr></tbody></table><p>コンパイラは、問題の箇所や、関連する宣言の位置を診断に含めることがあります。Clangは回復できる範囲で構文解析を続け、後続の問題も報告します。最初に表示された位置の周囲と、その直前の文を確認すると、エラーの連鎖を切り分けやすくなります。<a href="https://clang.llvm.org/docs/InternalsManual.html#error-handling" target="_blank" rel="noreferrer">Clang ASTのエラー回復</a></p><h2 id="clangでastを読む" tabindex="-1">ClangでASTを読む <a class="header-anchor" href="#clangでastを読む" aria-label="Permalink to &quot;ClangでASTを読む&quot;">​</a></h2><p>例を <code>adjust.cpp</code> として保存し、Clangを使える端末で実行します。<code>-fsyntax-only</code> はフロントエンドで止める指定です。<code>-Xclang</code> を通して、ASTを表示するオプションをフロントエンドに渡します。<a href="https://clang.llvm.org/docs/IntroductionToTheClangAST.html#examining-the-ast" target="_blank" rel="noreferrer">Clang公式のASTダンプ手順</a></p><div class="language-powershell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">clang</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">++</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> -</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">std</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">c</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">+</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">+17</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> -</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">fsyntax</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">only </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Xclang </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">ast</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">dump adjust.cpp</span></span></code></pre></div><p>出力で <code>adjust</code> の <code>FunctionDecl</code> を探し、<code>ReturnStmt</code> の下にある演算をたどります。次は関連するノードと型を抜き出したものです。<code>LValueToRValue</code> は、引数を指す式から値を読み出す変換です。<code>IntegralToFloating</code> が掛かるのは、<code>step</code> 単体ではなく乗算の結果です。</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ReturnStmt</span></span>
<span class="line"><span>└─ BinaryOperator &#39;double&#39; &#39;+&#39;</span></span>
<span class="line"><span>   ├─ ImplicitCastExpr &#39;double&#39; &lt;LValueToRValue&gt;</span></span>
<span class="line"><span>   │  └─ DeclRefExpr &#39;double&#39; value</span></span>
<span class="line"><span>   └─ ImplicitCastExpr &#39;double&#39; &lt;IntegralToFloating&gt;</span></span>
<span class="line"><span>      └─ BinaryOperator &#39;unsigned int&#39; &#39;*&#39;</span></span>
<span class="line"><span>         ├─ ImplicitCastExpr &#39;unsigned int&#39; &lt;LValueToRValue&gt;</span></span>
<span class="line"><span>         │  └─ DeclRefExpr &#39;unsigned int&#39; step</span></span>
<span class="line"><span>         └─ IntegerLiteral &#39;unsigned int&#39; 2</span></span></code></pre></div><p>演算の型が決まると、後続の処理は加算や変換を型付き命令にできます。<a href="/study/compilers/llvm-ir-and-ssa.html">LLVM IRとSSA</a></p>`,18)])])}const u=s(l,[["render",r]]);export{k as __pageData,u as default};
